const FNV_OFFSET: u64 = 14695981039346656037
const FNV_PRIME: u64 = 1099511628211

// Each distinct run of ASCII letters, lowercased, with how often it occurs.
fn count_words(data: [u8]) -> [(str, int)]
  ex count_words("Go go, GO!".bytes()) == [("go", 3)]
{
  // Open addressing: each slot holds an entry index + 1, or 0 when empty.
  var slots: [int] = []
  for _k in 0..1024 {
    slots.push(0)
  }
  var mask = 1023
  var hashes: [u64] = []
  var offs: [int] = []
  var lens: [int] = []
  var counts: [int] = []
  // The lowercased bytes of every distinct word, back to back.
  var arena: [u8] = []
  let n = data.len()
  var i = 0
  while i < n {
    if (data[i] | 32) -% 'a' >= 26 {
      i += 1
      continue
    }
    let start = i
    var h = FNV_OFFSET
    while i < n {
      let c = data[i] | 32
      if c -% 'a' >= 26 {
        break
      }
      h = (h ^ u64(c)) *% FNV_PRIME
      i += 1
    }
    let len = i - start
    var slot = int(h >> 40) & mask
    while true {
      let e = slots[slot]
      if e == 0 {
        offs.push(arena.len())
        for k in start..i {
          arena.push(data[k] | 32)
        }
        hashes.push(h)
        lens.push(len)
        counts.push(1)
        slots[slot] = offs.len()
        if offs.len() * 2 > mask {
          mask = grow(inout slots, hashes)
        }
        break
      }
      let idx = e - 1
      if hashes[idx] == h && lens[idx] == len && same_word(arena, at: offs[idx], data, start, len) {
        counts[idx] += 1
        break
      }
      slot = (slot + 1) & mask
    }
  }
  var result: [(str, int)] = []
  for idx, off in offs {
    let w = str.from_bytes(arena[off..off + lens[idx]]) else ""
    result.push((w, counts[idx]))
  }
  return result
}

// Whether `arena[at..at + len]` equals `data[start..start + len]` lowercased.
fn same_word(arena: [u8], at: int, data: [u8], start: int, len: int) -> bool {
  for k in 0..len {
    if arena[at + k] != (data[start + k] | 32) {
      return false
    }
  }
  return true
}

// Doubles the slot table and reinserts every entry; returns the new mask.
fn grow(slots: inout [int], hashes: [u64]) -> int {
  let size = slots.len() * 2
  let mask = size - 1
  var fresh: [int] = []
  for _k in 0..size {
    fresh.push(0)
  }
  for idx, h in hashes {
    var slot = int(h >> 40) & mask
    while fresh[slot] != 0 {
      slot = (slot + 1) & mask
    }
    fresh[slot] = idx + 1
  }
  slots = fresh
  return mask
}
